// ELEMENTS (sobre o vídeo, fundo transparente):
// 1. Véu navy em gradiente no fundo e cantos de visor ciano
// 2. Marca (brand) no topo com filete ciano
// 3. Cartão de vidro navy: avião de papel em traço que se desenha e voa, chamada (anim.text) em Cormorant,
//    sub em Poppins
// 4. Pílula coral com texto navy (pill) em pillAt (s)
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0E1626";
const NAVY_RGB = "14,22,38";
const CYAN = "#05B8E6";
const CORAL = "#F06052";
const WHITE = "#F4F1EA";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.8));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const IadCtaOverlay: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const brand = String(p.brand ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const pill = String(p.pill ?? "").trim();
  const pillAt = Number(p.pillAt ?? 3) || 3;
  const cardAt = Number(p.cardAt ?? 0.3);
  const title = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const card = show(cardAt, 0.6);
  const plane = show(cardAt + 0.3, 0.9);
  const fly = show(cardAt + 1.2, 0.8, Easing.inOut(Easing.cubic));
  const c = show(0.1, 0.9);
  const L = 90 * u * c;
  const m = 46 * u;
  const corner = { position: "absolute" as const, width: L, height: L, borderColor: CYAN, borderStyle: "solid" as const, borderWidth: 0 };
  const pk = show(pillAt, 0.5, BACK);

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: "55%", background: `linear-gradient(0deg, rgba(${NAVY_RGB},0.9) 0%, rgba(${NAVY_RGB},0.55) 55%, rgba(${NAVY_RGB},0) 100%)`, opacity: show(0, 0.6) }} />
      <div style={{ ...corner, left: m, top: m, borderLeftWidth: 4 * u, borderTopWidth: 4 * u }} />
      <div style={{ ...corner, right: m, top: m, borderRightWidth: 4 * u, borderTopWidth: 4 * u }} />
      <div style={{ ...corner, left: m, bottom: m, borderLeftWidth: 4 * u, borderBottomWidth: 4 * u }} />
      <div style={{ ...corner, right: m, bottom: m, borderRightWidth: 4 * u, borderBottomWidth: 4 * u }} />
      {brand ? (
        <div style={{ position: "absolute", top: 150 * u, left: 0, right: 0, display: "flex", justifyContent: "center", alignItems: "center", gap: 16 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.3em", color: WHITE, opacity: show(0.2), textShadow: "0 2px 16px rgba(0,0,0,0.5)" }}>
          <div style={{ width: 50 * u * show(0.2, 0.8), height: 3 * u, background: CYAN }} />
          {brand}
          <div style={{ width: 50 * u * show(0.2, 0.8), height: 3 * u, background: CYAN }} />
        </div>
      ) : null}
      <div style={{ position: "absolute", left: 80 * u, right: 80 * u, bottom: 230 * u, background: `rgba(${NAVY_RGB},0.82)`, backdropFilter: `blur(${10 * u}px)`, borderTop: `${3 * u}px solid ${CYAN}`, padding: `${44 * u}px ${44 * u}px`, display: "flex", flexDirection: "column", gap: 22 * u, opacity: card, transform: `translateY(${(1 - card) * 50 * u}px)` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 30 * u }}>
          <svg width={120 * u} height={120 * u} viewBox="0 0 48 48" style={{ overflow: "visible", flexShrink: 0, transform: `translate(${fly * 14 * u}px, ${-fly * 10 * u}px) rotate(${fly * -6}deg)` }}>
            <path d="M5 23 L43 6 L32 42 L22 29 Z M22 29 L43 6 M22 29 V38 L27 34" fill="none" stroke={CYAN} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - plane} />
            <path d="M2 34 Q8 30 12 34 T22 34" fill="none" stroke={CORAL} strokeWidth={2} strokeLinecap="round" strokeDasharray="2 4" opacity={fly} />
          </svg>
          <div style={{ fontFamily: FONTS.display, fontWeight: 500, fontSize: 96 * u, lineHeight: 1, color: WHITE }}>{title}</div>
        </div>
        {sub ? <div style={{ fontFamily: FONTS.body, fontWeight: 500, fontSize: 40 * u, color: "rgba(244,241,234,0.85)", opacity: show(cardAt + 0.6) }}>{sub}</div> : null}
        {pill ? (
          <div style={{ alignSelf: "flex-start", background: CORAL, color: NAVY, fontFamily: FONTS.body, fontWeight: 700, fontSize: 32 * u, letterSpacing: "0.16em", textTransform: "uppercase", padding: `${16 * u}px ${34 * u}px`, transform: `scale(${pk})`, opacity: pk > 0 ? 1 : 0 }}>{pill}</div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default IadCtaOverlay;
